import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public class Patch implements Opcodes{
 static String P="dev/zomboid/npcprobe/Probe",PART="dev/zomboid/npcprobe/Parts",C="dev/zomboid/npcprobe/Commands";static int changes;
 static MethodInsnNode call(String o,String n,String d){return new MethodInsnNode(INVOKESTATIC,o,n,d,false);}static void changed(String s){changes++;System.out.println("Patched "+s);}
 static void verify(ClassNode c)throws Exception{for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 static void guard(MethodNode m,InsnList h){LabelNode old=new LabelNode();h.add(new JumpInsnNode(IFEQ,old));h.add(new InsnNode(RETURN));h.add(old);h.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(h);}
 static byte[] patch(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int oldchanges=changes;
  if(c.name.equals("mod/cdv/tnpc/TNPC"))for(MethodNode m:c.methods){
   if(m.name.equals("registerCommands")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,1));h.add(call(C,"register","(Ljava/lang/Object;)V"));m.instructions.insert(h);changed("admin test commands");}
   if(m.name.equals("<init>"))for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==RETURN){InsnList h=new InsnList();h.add(new FieldInsnNode(GETSTATIC,"net/neoforged/neoforge/common/NeoForge","EVENT_BUS","Lnet/neoforged/bus/api/IEventBus;"));h.add(new LdcInsnNode(Type.getObjectType("dev/zomboid/npcprobe/Events")));h.add(new MethodInsnNode(INVOKEINTERFACE,"net/neoforged/bus/api/IEventBus","register","(Ljava/lang/Object;)V",true));m.instructions.insertBefore(n,h);changed("final damage listener");}
  }
  if(c.name.equals("mod/cdv/tnpc/tactical/CalmBrain"))for(MethodNode m:c.methods)if(m.name.equals("ignoreDamage")){LabelNode old=new LabelNode();InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(call(P,"marked","(Ljava/lang/Object;)Z"));h.add(new JumpInsnNode(IFEQ,old));h.add(new InsnNode(ICONST_0));h.add(new InsnNode(IRETURN));h.add(old);h.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(h);changed("friendly test NPC remains damageable");}
  if(c.name.equals("mod/cdv/tnpc/entity/AutoGunOperator")){
   for(MethodNode m:c.methods){
    if(m.name.equals("tick")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(call(P,"prepare","(Ljava/lang/Object;)V"));m.instructions.insert(h);int hooks=0;for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof MethodInsnNode mc&&mc.name.equals("onTickServerSide")){LabelNode old=new LabelNode();InsnList a=new InsnList();a.add(new VarInsnNode(ALOAD,0));a.add(call(P,"marked","(Ljava/lang/Object;)Z"));a.add(new JumpInsnNode(IFEQ,old));a.add(new InsnNode(RETURN));a.add(old);a.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(n,a);hooks++;}if(hooks!=1)throw new IllegalStateException("native tick path");changed("isolate test AI while retaining native TaCZ and physics ticks");}
    if(m.name.equals("onTickServerSide")){int hooks=0;for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof MethodInsnNode mc&&mc.owner.equals("mod/cdv/tnpc/tactical/BanditBrain")&&mc.name.equals("tick")){mc.owner=P;mc.name="dispatch";hooks++;}if(hooks!=1)throw new IllegalStateException("bandit dispatcher");changed("test behavior dispatch");}
    if(m.name.equals("die")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(call(P,"blockDeath","(Ljava/lang/Object;Ljava/lang/Object;)Z"));guard(m,h);changed("critical part death adaptation and true final deaths");}
    if(m.name.equals("hurt")){LabelNode old=new LabelNode();InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new VarInsnNode(FLOAD,2));h.add(call(P,"hurt","(Ljava/lang/Object;Ljava/lang/Object;F)Ljava/lang/Boolean;"));h.add(new InsnNode(DUP));h.add(new JumpInsnNode(IFNULL,old));h.add(new MethodInsnNode(INVOKEVIRTUAL,"java/lang/Boolean","booleanValue","()Z",false));h.add(new InsnNode(IRETURN));h.add(old);h.add(new FrameNode(F_SAME1,0,null,1,new Object[]{"java/lang/Boolean"}));h.add(new InsnNode(POP));m.instructions.insert(h);changed("downed finishers");}
    if(m.name.equals("isAlliedTo")){LabelNode old=new LabelNode();InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(call(P,"allied","(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Boolean;"));h.add(new InsnNode(DUP));h.add(new JumpInsnNode(IFNULL,old));h.add(new MethodInsnNode(INVOKEVIRTUAL,"java/lang/Boolean","booleanValue","()Z",false));h.add(new InsnNode(IRETURN));h.add(old);h.add(new FrameNode(F_SAME1,0,null,1,new Object[]{"java/lang/Boolean"}));h.add(new InsnNode(POP));m.instructions.insert(h);changed("safe ownership and ally rules");}
    if(m.name.equals("shouldShowName")){m.instructions.insert(new VarInsnNode(ALOAD,0));m.instructions.insert(m.instructions.getFirst(),call(P,"marked","(Ljava/lang/Object;)Z"));LabelNode old=new LabelNode();InsnList h=new InsnList();h.add(new JumpInsnNode(IFEQ,old));h.add(new InsnNode(ICONST_1));h.add(new InsnNode(IRETURN));h.add(old);h.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(m.instructions.getFirst().getNext(),h);changed("visible probe name");}
   }
   MethodNode interaction=new MethodNode(ACC_PUBLIC,"mobInteract","(Lnet/minecraft/world/entity/player/Player;Lnet/minecraft/world/InteractionHand;)Lnet/minecraft/world/InteractionResult;",null,null);InsnList h=interaction.instructions;LabelNode normal=new LabelNode();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new VarInsnNode(ALOAD,2));h.add(call(P,"interact","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;"));h.add(new InsnNode(DUP));h.add(new JumpInsnNode(IFNULL,normal));h.add(new TypeInsnNode(CHECKCAST,"net/minecraft/world/InteractionResult"));h.add(new InsnNode(ARETURN));h.add(normal);h.add(new FrameNode(F_SAME1,0,null,1,new Object[]{"java/lang/Object"}));h.add(new InsnNode(POP));h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new VarInsnNode(ALOAD,2));h.add(new MethodInsnNode(INVOKESPECIAL,c.superName,"mobInteract",interaction.desc,false));h.add(new InsnNode(ARETURN));c.methods.add(interaction);changed("bandage and timed revival interaction");
  }
  if(oldchanges==changes)return b;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);verify(v);return w.toByteArray();
 }
 static byte[] events(){ClassWriter w=new ClassWriter(0);w.visit(V21,ACC_PUBLIC|ACC_FINAL,"dev/zomboid/npcprobe/Events",null,"java/lang/Object",null);MethodVisitor m=w.visitMethod(ACC_PUBLIC|ACC_STATIC,"damage","(Lnet/neoforged/neoforge/event/entity/living/LivingDamageEvent$Post;)V",null,null);m.visitAnnotation("Lnet/neoforged/bus/api/SubscribeEvent;",true).visitEnd();m.visitCode();m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESTATIC,PART,"post","(Ljava/lang/Object;)V",false);m.visitInsn(RETURN);m.visitMaxs(1,1);m.visitEnd();w.visitEnd();return w.toByteArray();}
 public static void main(String[] args)throws Exception{Map<String,byte[]> out=new TreeMap<>();try(ZipFile z=new ZipFile(args[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] b=z.getInputStream(e).readAllBytes();out.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}
  try(var paths=Files.walk(Path.of(args[2]))){for(Path p:paths.filter(p->p.toString().endsWith(".class")).toList())out.put(Path.of(args[2]).relativize(p).toString(),Files.readAllBytes(p));}out.put("dev/zomboid/npcprobe/Events.class",events());
  try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:out.entrySet()){ZipEntry entry=new ZipEntry(e.getKey());entry.setTime(0);z.putNextEntry(entry);z.write(e.getValue());z.closeEntry();}}System.out.println("Completed "+changes+" patches.");
 }
}
